#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <sys/stat.h>
#include <errno.h>
#include <pthread.h>

#define MAX_PATH 512
#define RECEIPT_DIR "/var/payments/receipts"
#define PENDING_DIR "/var/payments/pending"

static volatile sig_atomic_t shutting_down = 0;
static pthread_mutex_t txn_lock = PTHREAD_MUTEX_INITIALIZER;

typedef struct {
    char merchant_id[64];
    char txn_id[128];
    double amount;
    int finalized;
} Transaction;

static void signal_handler(int sig) {
    (void)sig;
    shutting_down = 1;
}

/* Normalize path component: collapse repeated separators, reject control chars */
static int sanitize_component(const char *input, char *output, size_t outlen) {
    size_t i = 0, j = 0;
    if (!input || !output || outlen == 0) return -1;

    for (i = 0; input[i] && j < outlen - 1; i++) {
        if (input[i] < 0x20) return -1;  /* reject control chars */
        if (input[i] == '/') return -1;  /* reject path separators */
        if (input[i] == '.' && i > 0 && input[i-1] == '.') return -1;
        output[j++] = input[i];
    }
    output[j] = '\0';
    return (j > 0) ? 0 : -1;
}

/* Build safe path from base directory and components */
static int build_receipt_path(char *dest, size_t destlen,
                              const char *base, const char *merchant,
                              const char *txn_id) {
    char safe_merchant[64];
    char safe_txn[128];

    if (sanitize_component(merchant, safe_merchant, sizeof(safe_merchant)) != 0)
        return -1;
    if (sanitize_component(txn_id, safe_txn, sizeof(safe_txn)) != 0)
        return -1;

    int n = snprintf(dest, destlen, "%s/%s/%s.receipt", base, safe_merchant, safe_txn);
    if (n < 0 || (size_t)n >= destlen) return -1;
    return 0;
}

/* During graceful shutdown, flush pending transactions to receipt files */
static int flush_pending_transaction(Transaction *txn) {
    char path[MAX_PATH];
    char pending_path[MAX_PATH];
    char safe_txn[128];
    FILE *fp;

    /* Build path for the finalized receipt */
    if (build_receipt_path(path, sizeof(path), RECEIPT_DIR,
                           txn->merchant_id, txn->txn_id) != 0) {
        fprintf(stderr, "Invalid path for txn %s\n", txn->txn_id);
        return -1;
    }

    /* During shutdown, also write to pending dir for recovery.
     * Re-sanitize txn_id for the pending path as well */
    if (sanitize_component(txn->txn_id, safe_txn, sizeof(safe_txn)) != 0)
        return -1;
    snprintf(pending_path, sizeof(pending_path), "%s/%s",
             PENDING_DIR, safe_txn);

    /* Write receipt */
    fp = fopen(path, "w");
    if (!fp) {
        /* If receipt dir doesn't exist for merchant, create it */
        char dir[MAX_PATH];
        char safe_merchant[64];
        if (sanitize_component(txn->merchant_id, safe_merchant, sizeof(safe_merchant)) != 0)
            return -1;
        snprintf(dir, sizeof(dir), "%s/%s", RECEIPT_DIR, safe_merchant);
        mkdir(dir, 0750);
        fp = fopen(path, "w");
        if (!fp) return -1;
    }
    fprintf(fp, "TXN:%s\nAMOUNT:%.2f\nMERCHANT:%s\nSTATUS:COMPLETED\n",
            txn->txn_id, txn->amount, txn->merchant_id);
    fclose(fp);

    /* Write pending marker for crash recovery */
    fp = fopen(pending_path, "w");
    if (fp) {
        fprintf(fp, "PENDING_FLUSH:%s\n", txn->txn_id);
        fclose(fp);
    }

    txn->finalized = 1;
    return 0;
}

/* Process incoming payment - called from network handler */
int process_payment(const char *merchant, const char *transaction_id, double amount) {
    Transaction txn;
    int result;

    if (!merchant || !transaction_id || amount <= 0.0)
        return -1;

    if (strlen(merchant) >= sizeof(txn.merchant_id) ||
        strlen(transaction_id) >= sizeof(txn.txn_id))
        return -1;

    pthread_mutex_lock(&txn_lock);

    memset(&txn, 0, sizeof(txn));
    strncpy(txn.merchant_id, merchant, sizeof(txn.merchant_id) - 1);
    strncpy(txn.txn_id, transaction_id, sizeof(txn.txn_id) - 1);
    txn.amount = amount;
    txn.finalized = 0;

    if (shutting_down) {
        /* During graceful shutdown, immediately flush */
        result = flush_pending_transaction(&txn);
    } else {
        /* Normal operation: just validate and queue (simplified) */
        char path[MAX_PATH];
        result = build_receipt_path(path, sizeof(path), RECEIPT_DIR,
                                    txn.merchant_id, txn.txn_id);
    }

    pthread_mutex_unlock(&txn_lock);
    return result;
}

int main(int argc, char *argv[]) {
    struct sigaction sa;
    memset(&sa, 0, sizeof(sa));
    sa.sa_handler = signal_handler;
    sigaction(SIGTERM, &sa, NULL);
    sigaction(SIGINT, &sa, NULL);

    printf("Payment processor started (PID %d)\n", getpid());

    /* Simulate processing loop */
    while (!shutting_down) {
        sleep(1);
    }

    printf("Graceful shutdown initiated...\n");

    /* In real code, would iterate pending queue here */

    printf("Shutdown complete.\n");
    return 0;
}
